"""Render the configuration reference (docs/configuration.md) from the dataclass schemas, so the
documentation can never drift from the code: a test fails if the committed file is out of date."""
from __future__ import annotations

import dataclasses
import inspect
import typing
from dataclasses import MISSING, fields, is_dataclass

from snapdragon.config.schema import Config

HEADER = """# Configuration reference

<!-- generated by scripts/gen_config_docs.py; do not edit by hand -->

Configs are YAML files with five sections (`model`, `data`, `optim`, `train`, and nested
`optim.scheduler`, `train.eval`, `data.sources`). A file may `extends:` another (relative path, deep-merged),
and any value can be overridden on the command line with `section.key=value`, e.g.
`python scripts/train.py --config configs/train/pretrain-16gb.yaml train.micro_batch_size=2`.
Unknown keys are rejected with a suggestion.
"""


def _type_name(tp) -> str:
    if is_dataclass(tp):
        return tp.__name__
    origin = typing.get_origin(tp)
    if origin is None:
        return getattr(tp, "__name__", str(tp))
    args = ", ".join(_type_name(a) for a in typing.get_args(tp))
    return f"{getattr(origin, '__name__', str(origin))}[{args}]"


def _default(f: dataclasses.Field) -> str:
    if f.default is not MISSING:
        return repr(f.default)
    if f.default_factory is not MISSING:
        value = f.default_factory()
        return f"{type(value).__name__}()" if is_dataclass(value) else repr(value)
    return "(required)"


BLURBS = {
    "model": "Architecture of the transformer. `head_dim: 0` means `d_model // n_heads`; `act_ckpt` trades "
             "compute for activation memory (`none` | `selective` | `sac` | `full`).",
    "data": "Where tokens come from and how they are batched. `sources` are prepared datasets mixed by weight.",
    "data.sources": "One tokenized dataset in the mixture.",
    "optim": "Muon trains hidden matrices, (8-bit) AdamW trains embeddings and gains.",
    "optim.scheduler": "Learning-rate schedule: `wsd` (warmup-stable-decay, stoppable anywhere), `cosine` or `linear`.",
    "train": "The training loop: batch layout, precision, curriculum, checkpointing, resume.",
    "train.eval": "Validation loss and benchmark cadence during training.",
}


def _section(title: str, cls: type) -> list[str]:
    hints = typing.get_type_hints(cls)
    doc = BLURBS.get(title, "")
    if not doc:
        auto = inspect.getdoc(cls) or ""
        doc = "" if auto.startswith(f"{cls.__name__}(") else auto.split("\n\n")[0].replace("\n", " ")
    out = [f"## `{title}`", ""]
    if doc:
        out += [doc, ""]
    out += ["| key | type | default |", "|---|---|---|"]
    for f in fields(cls):
        out.append(f"| `{f.name}` | `{_type_name(hints[f.name])}` | `{_default(f)}` |")
    out.append("")
    return out


def render_config_reference() -> str:
    cfg_hints = typing.get_type_hints(Config)
    lines = [HEADER]
    seen: set[type] = set()

    def visit(title: str, cls: type) -> None:
        if cls in seen:
            return
        seen.add(cls)
        lines.extend(_section(title, cls))
        hints = typing.get_type_hints(cls)
        for f in fields(cls):
            tp = hints[f.name]
            inner = typing.get_args(tp)[0] if typing.get_origin(tp) is list and typing.get_args(tp) else tp
            if is_dataclass(inner):
                visit(f"{title}.{f.name}" if title != "<root>" else f.name, inner)

    for f in fields(Config):
        visit(f.name, cfg_hints[f.name])
    return "\n".join(lines).rstrip() + "\n"
